from itertools import combinations, product
import heapq


def _build_jobs(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best = None
        best_value = None
        best_ids = None
        for subset in combinations(jobs, k):
            ids = {job["id"] for job in subset}
            if not mandatory <= ids or ids & blocked:
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            active = []
            valid = True
            for job in sorted(subset, key=lambda row: (row["start"], row["end"])):
                while active and active[0] <= job["start"]:
                    heapq.heappop(active)
                heapq.heappush(active, job["end"])
                if len(active) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(job["value"] for job in subset)
            names = sorted(ids)
            if (best is None or value > best_value or
                    (value == best_value and
                     (names < best_ids if tie == "smallest" else names > best_ids))):
                best = subset
                best_value = value
                best_ids = names
        if best is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_06():
    def rounded(n, d, mode):
        q, r = divmod(n, d)
        return q + (1 if mode == "half_up" and 2 * r >= d else 0)

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for pos, event in enumerate(data["events"]):
            seq = event.get("sequence", 0)
            if seq > cutoff:
                continue
            ident = event.get("id", "anonymous:" + str(pos))
            key = (seq, event.get("revision", 0), pos)
            if ident not in winners or key > winners[ident][0]:
                winners[ident] = (key, event)
        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            tax = rounded(net * event.get("tax_bp", 0), 10000, data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        choices = []
        for name in names:
            forbidden = set(blocked.get(name, []))
            pin = pins.get(name)
            versions = [row["version"] for row in packages[name]
                        if row["version"] not in forbidden and
                        (pin is None or row["version"] == pin)]
            choices.append([None] + versions)

        best_vector = None
        best = None
        for selection in product(*choices):
            assigned = dict(zip(names, selection))
            rows = {name: next((row for row in packages[name]
                               if row["version"] == assigned[name]), None)
                    for name in names}
            edges = {name: [] for name in names}
            closure = set()
            pending = []
            valid = True
            for name, bounds in data["roots"].items():
                version = assigned[name]
                if version is None or not bounds[0] <= version <= bounds[1]:
                    valid = False
                    break
                pending.append(name)
            while valid and pending:
                name = pending.pop()
                if name in closure:
                    continue
                closure.add(name)
                row = rows[name]
                if row is None:
                    valid = False
                    break
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    version = assigned[target]
                    if version is None or not dep["min"] <= version <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(target)
                    pending.append(target)
            if not valid or any(assigned[name] is not None and name not in closure
                                for name in names):
                continue
            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            if not all(visit(name) for name in names):
                continue
            vector = tuple(-1 if assigned[name] is None else assigned[name]
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = {name: assigned[name] for name in names
                        if assigned[name] is not None}
        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": best}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bits = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        source = data["source"]
        initial_mask = bits.get(source, 0)
        start_state = (source, initial_mask, data["coupons"])
        dist = {start_state: data["start"]}
        queue = [(data["start"], source, initial_mask, data["coupons"])]
        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if dist.get(state) != time:
                continue
            if node == data["target"] and mask == full and remaining == 0:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    options.append((max(2, edge["duration"] - edge.get("discount", 0)),
                                    remaining - 1))
                for duration, left in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    next_mask = mask | bits.get(nxt, 0)
                    next_state = (nxt, next_mask, left)
                    if arrival < dist.get(next_state, float("inf")):
                        dist[next_state] = arrival
                        heapq.heappush(queue, (arrival, nxt, next_mask, left))
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _build_jobs(2, "smallest"),
    "component_02": _build_jobs(1, "largest"),
    "component_03": _build_jobs(2, "largest"),
    "component_04": _build_jobs(1, "smallest"),
    "component_05": _build_jobs(2, "smallest"),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
